  "knowledge": "High-Value Member",
  "description": "A fan with a paid subscription who consistently contributes significant financial value to the platform on a monthly basis.",
  "definition": "A fan is a High-Value Member if they are a Premium Member and their Fan Financial Value (FFV) is greater than $50 per month."
}

